"""Report content, part F: Question 6.4 (real blurred photograph)."""
import math

from content_a import load, g, e, f


def section6_b(R):
    B = []
    val = R["q6_4_validation_on_synthetic_blur_of_photoD_crop"]
    sc = R["q6_4_single_crop_estimates"]
    te = R["q6_4_tile_estimate"]
    tv = R["q6_4_tile_estimator_validation_(split_tiles_of_D)"]
    dbl = R["q6_4_deblur"]
    n_ok = sum(1 for r in val["rows"] if abs((r["theta_comb"] - r["theta_true"] + 90) % 180 - 90) <= 2.0 and abs(r["L_comb"] - r["L_true"]) <= 0.1 * r["L_true"] + 0.5)
    B.append(("h2", "6.4 Estimate the blur from a real photograph, then remove it"))
    B.append(("p", "**Photographs.** Photograph C (`IMG_20261026_195635983.jpg`, 4080x3072, EXIF ISO 491, exposure 1/14 s = 0.07 s, f/1.87, 24 mm-equivalent) is the real motion-blurred photo; photograph D (`IMG_20261026_195702582.jpg`, ISO 722, 1/50 s, same room, different viewpoint) is a sharper photo used only as a *statistical control* in the spectral analysis (never for pixel-wise scores: C and D are not aligned and D is not the sharp version of C). The EXIF data do not record how the camera was held or moved; 1/14 s is much slower than the usual hand-holding guideline of 1/(35 mm-equivalent focal length) = 1/24 s, so camera shake is a plausible cause, but the metadata alone do not establish it. The visible blur is non-uniform (Figures 6.6 and 6.7: the window bars are smeared across tens of pixels, the floor and the door frame much less, the clock face is smeared along a curved path), so a uniform linear model can at best be a first approximation."))
    B.append(("p", "**Estimator 1: single-crop cepstrum + spectral comb (validated on synthetic blur).** For a 1024x1024 grey crop the Hann-windowed power spectrum is divided by its radial mean (whitening). (i) The *cepstrum* of this whitened log-spectrum (inverse FFT, radial trend removed) has a negative peak at the quefrency vector $L(\\cos\\theta,\\sin\\theta)$, because $\\log\\mathrm{sinc}^2(Ls)$ is periodic in $s$ with period $1/L$. (ii) A *comb score* then refines $(L,\\theta)$ by minimising the mean whitened log-spectrum on the predicted zero lines $s=m/L$ minus the mean on the half-way lines. The pair was tested on a crop of the sharp photograph D blurred synthetically with known $(L,\\theta)$ and without or with noise (2 grey levels): %d of %d cases ($L\\in\\{8,15,25,40,70\\}$, angles including 0, 0.7, 89.3, 90, 120, 160 degrees) are recovered within 2 degrees and 10%% (+0.5 px) of the truth; the four exceptions are the three noisy $L=8$ cases (L within 0.8 px, angle off by 3-5 degrees) and the noisy $L=15$, $\\theta=89.3^\\circ$ case, for which the cepstrum picked a low-quefrency lobe (4.7 px). Table 6.3 lists the validation." % (n_ok, len(val["rows"]))))
    rows = [[r["L_true"], r["theta_true"], r["noise_sigma_(0-255)"], f(r["L_cepstrum"], 1), f(r["theta_cepstrum"], 1), f(r["L_comb"], 1), f(r["theta_comb"], 1), f(r["theta_err_comb"], 1), f(r["L_err_comb"], 2)] for r in val["rows"]]
    B.append(("table", "Table 6.3. Single-crop estimator validation: 1024x1024 crop of photograph D blurred synthetically (circular boundary) with known L (px) and theta (deg), without and with additive noise (sigma in grey levels). Cepstrum estimate, comb-refined estimate and the errors of the latter.", ["L true", "theta true", "noise", "L cepstrum", "theta cepstrum", "L comb", "theta comb", "theta err", "L err"], rows, "rrrrrrrrr"))
    rows = []
    for r in sc:
        rows.append([r["photo"], r["crop"], "%d,%d" % (r["r0"], r["c0"]), f(r["cepstrum_L"], 1), f(r["cepstrum_theta"], 1), f(r["cepstrum_peak_z"], 1), f(r["comb_L"], 1), f(r["comb_theta"], 1), f(r["comb_z_vs_null"], 1)])
    B.append(("table", "Table 6.4. Single-crop estimator applied to native-resolution 1024x1024 crops of the real photographs (origins row,col). 'z (peak)' = z-score of the cepstral peak against its annulus; 'z (comb)' = comb score relative to 300 random (theta, L) draws: |z| < 3 means no stripe pattern.", ["photo", "crop", "origin", "L cepstrum", "theta cepstrum", "z (peak)", "L comb", "theta comb", "z (comb)"], rows, "llrrrrrrr"))
    ud = val["estimate_on_unblurred_crop"]
    B.append(("p", "**Result on the real photographs: no clean zero-line pattern.** On every crop of C and of the control D the cepstral peak lies at 4.5-6.4 px, at the lower edge of the search interval [4, 150], with the same behaviour on the sharp photograph D (and on the *unblurred* test crop itself the cepstrum reports a peak of z = %s at L = %s px: a large cepstral z-score is not evidence of blur, it is the low-quefrency lobe of the scene's own spectral envelope); the comb scores relative to random $(\\theta,L)$ are indistinguishable from chance ($|z|\\le1.9$). The single-crop spectra (Figure 6.4, bottom right) show the strong axis-aligned structure of the scene (bright vertical and horizontal bands) but **no periodic dark stripes**. This is the limitation the assignment anticipates: for real camera-shake blur the zero lines are not observable in a single crop, because (i) the blur is spatially non-uniform (different blur lengths in different parts of the crop average the sinc$^2$ pattern into a smooth decay), (ii) the scene's own spectrum and the noise/JPEG floor mask the side lobes, and (iii) the crop contains edges of all orientations. **A stripe pattern is therefore not forced from this estimator; its output is not used.**" % (f(ud["peak_z_score"], 1), f(ud["L"], 1))))
    B.append(("p", "**Estimator 2: tile-averaged, control-normalised spectral analysis (adopted).** Averaging the whitened log-spectrum over many different 512x512 tiles of the whole frame (35 tiles per photograph) cancels the scene content of each tile but keeps what is common: the blur and the global scene statistics (a room full of straight horizontal/vertical edges). The remaining scene anisotropy is cancelled with the tile-averaged spectrum of the sharper photograph D as a *control* (same room, same kind of content; a statement about spectral statistics, not a pixel-level reference). (a) *Direction:* blur along $\\theta$ removes energy at frequencies along $\\theta$; after whitening, the difference of the angular profiles of $S_C-S_D$ in the band 0.02-0.12 cycles/pixel is therefore *maximal perpendicular to the blur*; its maximum is at %s degrees (Figure 6.4, top middle), giving **$\\hat\\theta=%s^\\circ$** (nearly horizontal motion). The difference ranges from %s (along $\\theta\\approx0$: energy removed) to +%s (at 90 degrees). (b) *Length:* the double ratio $Q(f)=[S_C(f,\\hat\\theta)-S_C(f,\\hat\\theta+90^\\circ)]-[S_D(f,\\hat\\theta)-S_D(f,\\hat\\theta+90^\\circ)]$ estimates $\\log|H(f)|^2$ along the blur direction with the scene anisotropy cancelled. It falls from %s at 0.012 cycles/pixel to %s at 0.042 and then stays near a floor of about %s up to 0.15 cycles/pixel. The sharp periodic dips of a uniform box blur are replaced by weak undulations: the stripe contrast (value of $Q$ at $m/\\hat L$ minus the mean at the two half-way points; negative = dip) is %s for $m=1\\ldots5$ against %s for the box model, i.e. dips of the right sign at $m=1,2,3$ but only a fraction of the expected depth, so the stripes beyond the first are smeared. Only the first lobe is quantitatively informative; fitting $\\log[(\\mathrm{sinc}^2(Lf)+\\kappa)/(1+\\kappa)]$ ($\\kappa=0.02$ allows a floor) over $f\\le0.05$ gives **$\\hat L=%s$ px** (fit error within 25%% of its minimum for $L\\in[%s,%s]$). The first zero at $1/\\hat L=%s$ cycles/pixel is therefore the *estimated* spacing of the stripes; it is marked in Figure 6.4 (cyan lines at $m/\\hat L$, spacing %s cycles/pixel) but only the first stripe is clearly supported by the data (the later ones only weakly)." % (f(te["theta_hat_deg"] + 90, 1), f(te["theta_hat_deg"], 1), f(te["diff_min"], 2), f(te["diff_max"], 2), f(te["Q_first_points"][0], 2), f(te["Q_first_points"][2], 2), f(te["Q_floor_median_0.05-0.15"], 2), ", ".join(f(x, 2) for x in te["Q_dip_contrast_at_m/L_hat_m=1..5_(value at m/L minus mean of the two half-way points)"]), ", ".join(f(x, 2) for x in te["box_model_dip_contrast_m=1..5_(kappa=0.02)"]), f(te["L_hat_px"], 1), f(te["L_range_(sse<=1.25 min)"][0], 1), f(te["L_range_(sse<=1.25 min)"][1], 1), f(1 / te["L_hat_px"], 4), f(1 / te["L_hat_px"], 4))))
    rows = [[r["L_true"], r["theta_true"], f(r["theta_est"], 1), f(r["theta_err"], 1), f(r["L_est"], 1), "%.1f-%.1f" % tuple(r["L_range"]), f(r["L_err_%"], 1)] for r in tv]
    B.append(("table", "Table 6.5. Validation of estimator 2 on synthetic blur: the 35 tiles of photograph D are split into two disjoint sets; one set is blurred with known (L, theta) and its tile-averaged spectrum is compared with the other, unblurred half as control. The L = 40, theta = 90 case is not identified: its first zero (0.025 cycles/pixel) lies near the lower end of the fit band and the fit-error minimum is flat up to L = 100 (range column).", ["L true", "theta true", "theta est", "theta err (deg)", "L est", "L range (fit error <= 1.25 min)", "L err %"], rows, "rrrrrrr"))
    B.append(("fig", "figures/q6_real_spectra.png", "Real photographs. Top left: tile-averaged whitened log-spectrum of C (35 tiles of 512x512) with the estimated blur direction (cyan dashed); top middle: angular profile of C - D in the 0.02-0.12 c/px band (maximum perpendicular to the blur); top right: first-lobe fit error vs L. Bottom left: tile-averaged spectrum of the sharper D (energy along the horizontal frequency axis retained); bottom middle: double ratio Q(f) = log|H|^2 along the blur direction with the box model (cyan lines at m/L-hat); bottom right: a single 1024x1024 crop of C: no stripe pattern.", 1.0))
    B.append(("fig", "figures/q6_real_cepstrum.png", "Cepstra of the single window crops of C and D: the most negative peak (+) lies near the origin for both photographs (not a blur signature).", 0.75))
    B.append(("p", "**Why the dark stripes are perpendicular to the motion.** $H$ depends on $(f_x,f_y)$ only through $s=f_x\\cos\\theta+f_y\\sin\\theta$, the component of the frequency vector along the motion; $|H|=|\\mathrm{sinc}(Ls)|$ is therefore constant on lines $s=\\mathrm{const}$, which are perpendicular to $(\\cos\\theta,\\sin\\theta)$, and vanishes on the lines $s=m/L$. A blur along $x$ ($\\theta\\approx0$) produces vertical stripes in the spectrum; equivalently the image keeps its contrast for structures varying along $y$ (horizontal edges: spectral energy on the vertical frequency axis, preserved in C) and loses it for structures varying along $x$ (vertical bars: spectral energy on the horizontal frequency axis, suppressed in C by about 2 natural-log units relative to D)."))
    ks = dbl["K_sweep"]
    ad = dbl["adopted"]
    B.append(("h3", "Deblurring with the estimated PSF"))
    B.append(("p", "**Estimated parameters.** *Automatic estimate* (estimator 2, unchanged): $\\hat\\theta=%s^\\circ$, $\\hat L=%s$ px. **Adopted** PSF: the same values, no manual adjustment. For $K$ the noise level of the crop was measured from flat patches ($\\hat\\sigma_{RGB}=%s$ grey levels) and the signal variance of the crop is %s (RGB), so the constant noise-to-signal ratio is $K_{est}=\\overline{\\hat\\sigma^2/\\mathrm{var}}=%s$. Because the PSF is only approximately right, $K_{est}$ (derived from noise alone) is too small: Figure 6.6 shows $K=0.1,1,10,100,1000\\times K_{est}$ and Table 6.6 the fraction of output pixels outside [0,255] (a diagnostic of ringing and noise amplification, **not a quality score**). **Adopted $K=%s=10\\,K_{est}$**, chosen by inspection of the sweep as the compromise between sharpening and noise/ringing; no ground truth exists and this is a judgement." % (f(ad["theta_deg"], 1), f(ad["L"], 1), ", ".join(f(x, 2) for x in dbl["sigma_hat_RGB_(0-255)"]), ", ".join(f(x, 0) for x in dbl["signal_variance_RGB"]), e(dbl["K_estimated_(sigma^2/var)"], 2), e(ad["K"], 2))))
    rows = [[g(k["K/K_est"], 3), e(k["K"], 2), f(k["fraction_outside_0_255_%"], 1), f(k["min"], 0), f(k["max"], 0), f(k["rms_change_vs_input"], 1)] for k in ks]
    B.append(("table", "Table 6.6. Wiener deconvolution of the 1024x1024 window crop of photograph C with L = 33.0 px, theta = 3.8 deg: diagnostics of the output for five values of K (no reference exists: these are not PSNR/SSIM).", ["K / K_est", "K", "% pixels outside [0,255]", "min", "max", "RMS change vs blurred input"], rows, "rrrrrr"))
    B.append(("fig", "figures/q6_real_deblur.png", "Photograph C, window crop (native resolution, top-left 520x520 shown): blurred input and Wiener deconvolution with the estimated PSF for K = 0.1, 1, 10, 100, 1000 x K_est. The vertical bars and the ornament separate clearly at 1-10 x K_est; large K under-deconvolves.", 1.0))
    B.append(("fig", "figures/q6_real_other_crops.png", "The same global PSF (L = 33, theta = 3.8, adopted K) applied to three other crops of C (door, door frame/floor, wall clock): panel edges and the clock face are recovered, but ringing and curved double contours remain where the true blur differs from the global estimate (clock outline, left of the floor crop).", 1.0))
    B.append(("p", "**Qualitative evaluation (no ground truth, no PSNR/SSIM).** The deconvolution recovers detail that is invisible in the input: the window bars (thin dark gaps between narrow vertical bars) and the ornamental triangles, the door panel edges and mouldings, and the clock hands and numerals partially. Smaller $K$ gives sharper but noisier results with horizontal streaks (noise amplification where $|H|$ is small, Section 6.2); larger $K$ keeps the blur (the under-deconvolution of Section 6.3): at $1000K_{est}$ the output is essentially the dimmed, still-blurred image. As a control, deconvolving the sharper photograph D (which is not blurred along this direction) with the same PSF (Figure 6.8) produces ringing and over-sharpening instead of new detail, so what is recovered in C is real blur removal and not an artefact of the filter."))
    B.append(("fig", "figures/q6_real_control_D.png", "Control: photograph D (sharper), left; the same Wiener deconvolution with the PSF estimated from C, right: ringing and over-sharpening only.", 0.85))
    B.append(("p", "**Visible artefacts and the limits of the linear, spatially invariant motion model.** (1) *Ringing/overshoot* around high-contrast bars (dark and bright rims beside window bars; %s%% of the output pixels leave [0,255] at $K_{est}$ and %s%% at the adopted $K$): the PSF has zeros, the length estimate is only good to a few percent (range %s-%s px) and an error in $L$ moves the zeros away from the true ones. (2) *Non-uniform blur / camera rotation:* camera shake usually contains rotation as well as translation, so blur length and direction vary over the frame (rotation about the optical axis gives arc-shaped blur growing with the distance from the centre). The single global PSF fits the window region, is too long for the floor region and has the wrong shape at the clock: the clock outline shows curved double contours and a halo (Figure 6.7, right). (3) *Changing velocity:* camera shake is not constant-speed motion, the true PSF is not a box and has no clean zeros (the double ratio shows only weak, shallow undulations after the first lobe), so the box PSF reproduces the first lobe only. (4) *Clipped highlights and occlusion:* saturated pixels (the bright door and the tube light) do not follow the linear model (the recorded value is min(255, convolution)), and regions where objects move across the frame are not the convolution of one sharp image; ringing appears around them. (5) *Noise model:* the noise is not white (Section 5.2), so a scalar $K$ cannot be right at all frequencies." % (f(ks[1]["fraction_outside_0_255_%"], 0), f(ks[2]["fraction_outside_0_255_%"], 0), f(te["L_range_(sse<=1.25 min)"][0], 1), f(te["L_range_(sse<=1.25 min)"][1], 1))))
    B.append(("p", "**Reported values.** Estimated direction $\\hat\\theta=%s^\\circ$ (from $+x$ towards $+y$: almost horizontal), estimated length $\\hat L=%s$ px (at the native 4080x3072 resolution), scalar regularisation $K=%s$ (the noise-based $K_{est}=%s$ times 10). Automatic and adopted values of $\\theta$ and $L$ coincide; only $K$ was adjusted, by inspection." % (f(ad["theta_deg"], 1), f(ad["L"], 1), e(ad["K"], 2), e(dbl["K_estimated_(sigma^2/var)"], 2))))
    return B
